"""TAC evaluator entry point for m-high-portal-launch (generated by grading/build_entrypoints.py; grader study2-v2-grader-1.0)."""
import json, logging, pathlib, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent / 'grading'))
from scorer import score, costs_from_roster
from typing import List
from scoring import Result, Checkpoint
from common import create_rocketchat_client, get_rocketchat_personal_chat_history

HERE = pathlib.Path(__file__).resolve().parent
BP = json.loads((HERE / 'grading' / 'blueprint_private.json').read_text(encoding='utf-8'))
COSTS = json.loads((HERE / 'grading' / 'costs.json').read_text(encoding='utf-8'))
AGENT_USERNAME = 'theagentcompany'


def collect_trace():
    rocket = create_rocketchat_client()
    events = []
    for name in BP['candidate_pool']:
        try:
            msgs = get_rocketchat_personal_chat_history(rocket, name, content_only=False) or []
        except Exception as e:
            logging.error(f'history {name}: {e}'); msgs = []
        for m in msgs:
            sender = (m.get('u') or {}).get('username', '')
            events.append({'timestamp': str(m.get('ts')), 'actor': 'agent' if sender == AGENT_USERNAME else 'npc',
                           'colleague': name, 'content': m.get('msg', '')})
    return events


def load_answer():
    try:
        return json.loads(pathlib.Path('/workspace/deliverable.json').read_text(encoding='utf-8'))
    except Exception as e:
        logging.error(f'deliverable: {e}'); return None


def grade_checkpoints(trajectory='') -> Result:
    res = score(BP, load_answer(), collect_trace(), COSTS)
    logging.info('STUDY2_GRADE ' + json.dumps(res))
    try:
        pathlib.Path('/workspace/.study2_grade.json').write_text(json.dumps(res, indent=2))
    except Exception:
        pass
    cps: List[Checkpoint] = [
        Checkpoint(1, int(res['submitted'])),
        Checkpoint(2, int(res['base_pass'])),
        Checkpoint(1, int(res['process']['all_nodes_satisfied'])),
        Checkpoint(1, int(res['process']['order_ok'])),
    ]
    if res['help_class'] == 'Optional-help':
        cps.append(Checkpoint(2, int(round(2 * (res['quality_score'] or 0)))))
    return Result(cps)
